import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z, w = vars
    return y / (16 * x**3 + 1) + z / (16 * y**3 + 1) + w / (16 * z**3 + 1) + x / (16 * w**3 + 1)

cons = ({'type': 'eq', 'fun': lambda vars: np.sum(vars) - 1})
bounds = [(0, 1), (0, 1), (0, 1), (0, 1)]

min_val = float('inf')
for x in np.linspace(0, 1, 10):
    for y in np.linspace(0, 1-x, 10):
        for z in np.linspace(0, 1-x-y, 10):
            w = 1 - x - y - z
            res = minimize(objective, [x, y, z, w], bounds=bounds, constraints=cons)
            if res.success:
                min_val = min(min_val, res.fun)
print(f"Grid search min: {min_val}")
